require __DIR__ . '/config.php';

function admin_url(string $page = 'dashboard', array $params = []): string { return 'admin.php?' . http_build_query(['page'=>$page] + $params); }
function admin_upload(string $input): ?string {
    if (empty($_FILES[$input]['tmp_name']) || ($_FILES[$input]['error'] ?? UPLOAD_ERR_NO_FILE) === UPLOAD_ERR_NO_FILE) return null;
    if ($_FILES[$input]['error'] !== UPLOAD_ERR_OK || $_FILES[$input]['size'] > 5 * 1024 * 1024) throw new RuntimeException('Images must be valid files smaller than 5 MB.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$input]['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
    if (!isset($allowed[$mime])) throw new RuntimeException('Please upload a JPG, PNG, or WebP image.');
    $folder=APP_ROOT . '/assets/uploads'; if(!is_dir($folder) && !mkdir($folder,0755,true)) throw new RuntimeException('Could not create the uploads folder.');
    $relative='assets/uploads/'.bin2hex(random_bytes(12)).'.'.$allowed[$mime]; if(!move_uploaded_file($_FILES[$input]['tmp_name'],APP_ROOT.'/'.$relative)) throw new RuntimeException('Upload failed. Please try again.');
    return $relative;
}

if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??'';
    if ($action==='login') {
        verify_csrf();$stmt=db()->prepare('SELECT * FROM admins WHERE email=?');$stmt->execute([trim(strtolower($_POST['email']??''))]);$admin=$stmt->fetch();
        if($admin && password_verify($_POST['password']??'', $admin['password'])) { session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_name']=$admin['name'];redirect('admin.php'); }
        flash('admin_notice','That email and password do not match.');redirect('admin.php');
    }
    admin_required(); verify_csrf(); $pdo=db();
    try {
        if ($action==='logout'){$_SESSION=[];session_destroy();redirect('admin.php');}
        if ($action==='save_category') {
            $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('A category name is required.');$data=[$name,trim($_POST['description']??''),isset($_POST['active'])?1:0];
            if($id){$data[]=$id;$pdo->prepare('UPDATE categories SET name=?,description=?,active=? WHERE id=?')->execute($data);}else $pdo->prepare('INSERT INTO categories (name,description,active) VALUES (?,?,?)')->execute($data);
            flash('admin_notice','Category saved.');redirect(admin_url('categories'));
        }
        if ($action==='delete_category') {$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);flash('admin_notice','Category removed.');redirect(admin_url('categories'));}
        if ($action==='save_product') {
            $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));if(!$name||!$category||$price<=0)throw new RuntimeException('Name, category, and a valid price are required.');
            $main=admin_upload('main_image');$discount=trim($_POST['discount_price']??'');$base=[$category,$name,trim($_POST['description']??''),$price,$discount===''?null:(float)$discount,$stock,$_POST['gender']??'Women',trim($_POST['sizes']??''),trim($_POST['colors']??''),isset($_POST['featured'])?1:0,isset($_POST['is_new'])?1:0,$_POST['status']??'active'];
            if($id){$sql='UPDATE products SET category_id=?,name=?,description=?,price=?,discount_price=?,stock=?,gender=?,sizes=?,colors=?,is_featured=?,is_new=?,status=?'.($main?',image=?':'').' WHERE id=?';if($main)$base[]=$main;$base[]=$id;$pdo->prepare($sql)->execute($base);} else {$baseWithImage=[$category,$name,trim($_POST['description']??''),$price,$discount===''?null:(float)$discount,$stock,$_POST['gender']??'Women',trim($_POST['sizes']??''),trim($_POST['colors']??''),$main?:'https://images.unsplash.com/photo-1611930022073-b7a4ba5fcccd?auto=format&fit=crop&w=900&q=85',isset($_POST['featured'])?1:0,isset($_POST['is_new'])?1:0,$_POST['status']??'active'];$pdo->prepare('INSERT INTO products (category_id,name,description,price,discount_price,stock,gender,sizes,colors,image,is_featured,is_new,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($baseWithImage);$id=(int)$pdo->lastInsertId();}
            if(!empty($_FILES['gallery']['name'][0]))foreach($_FILES['gallery']['name'] as $index=>$_){if($_FILES['gallery']['error'][$index]===UPLOAD_ERR_NO_FILE)continue;$_FILES['single_gallery']=['name'=>$_FILES['gallery']['name'][$index],'type'=>$_FILES['gallery']['type'][$index],'tmp_name'=>$_FILES['gallery']['tmp_name'][$index],'error'=>$_FILES['gallery']['error'][$index],'size'=>$_FILES['gallery']['size'][$index]];$path=admin_upload('single_gallery');if($path)$pdo->prepare('INSERT INTO product_images (product_id,path) VALUES (?,?)')->execute([$id,$path]);}
            flash('admin_notice','Product saved successfully.');redirect(admin_url('products'));
        }
        if ($action==='delete_product') {$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);flash('admin_notice','Product removed.');redirect(admin_url('products'));}
        if ($action==='order_status') {$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('admin_notice','Order status updated.');redirect(admin_url('orders',['detail'=>(int)$_POST['id']]));}
        if ($action==='save_settings') {foreach(['store_name','store_description','contact_phone','contact_email','store_address','currency','delivery_fee','free_delivery_threshold','instagram'] as $key)$pdo->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$key,trim($_POST[$key]??'')]);flash('admin_notice','Store settings updated.');redirect(admin_url('settings'));}
    } catch(Throwable $e){flash('admin_notice',$e->getMessage());redirect('admin.php');}
}

if(empty($_SESSION['admin_id'])) admin_login(); else admin_app();

