function admin_dashboard(): void {$pdo=db();$stats=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Pending'")->fetchColumn(),'delivered'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Delivered'")->fetchColumn(),'sales'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn()];$recent=$pdo->query('SELECT o.*,c.full_name FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 5')->fetchAll();$low=$pdo->query('SELECT name,stock FROM products WHERE stock<=5 ORDER BY stock ASC LIMIT 5')->fetchAll();?>
<section class="stat-grid"><article><small>Total products</small><b><?=$stats['products']?></b><span>In your active edit</span></article><article><small>Total orders</small><b><?=$stats['orders']?></b><span><?=$stats['pending']?> awaiting attention</span></article><article><small>Delivered</small><b><?=$stats['delivered']?></b><span>Orders completed</span></article><article><small>Total sales</small><b><?=money($stats['sales'])?></b><span>Excluding cancellations</span></article></section><section class="admin-two-col"><article class="panel"><div class="panel-heading"><div><p class="eyebrow">sales overview</p><h2>Your momentum</h2></div><span class="chart-key">Orders this month</span></div><div class="chart"><i style="height:27%"></i><i style="height:50%"></i><i style="height:37%"></i><i style="height:75%"></i><i style="height:56%"></i><i style="height:91%"></i><i style="height:70%"></i><i style="height:83%"></i></div><div class="chart-labels"><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span><span>Sat</span><span>Sun</span><span>Today</span></div></article><article class="panel low-stock"><div class="panel-heading"><div><p class="eyebrow">inventory note</p><h2>Low in stock</h2></div><a href="<?=admin_url('inventory')?>">View all →</a></div><?php if($low):foreach($low as $item):?><div><span><?=h($item['name'])?></span><b><?=$item['stock']?> left</b></div><?php endforeach;else:?><p>Everything is looking beautifully stocked.</p><?php endif;?></article></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">latest activity</p><h2>Recent orders</h2></div><a href="<?=admin_url('orders')?>">All orders →</a></div><?php if($recent):?><div class="admin-table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($recent as $order):?><tr><td><a href="<?=admin_url('orders',['detail'=>$order['id']])?>"><?=h($order['order_number'])?></a></td><td><?=h($order['full_name'])?></td><td><?=date('M j, Y',strtotime($order['created_at']))?></td><td><span class="admin-status <?=order_status_class($order['status'])?>"><?=h($order['status'])?></span></td><td><?=money((float)$order['total'])?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="admin-empty">Your first customer order will appear here.</div><?php endif;?></section><?php }

function admin_products(): void {$pdo=db();$search=trim($_GET['q']??'');$sql='SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id';$params=[];if($search){$sql.=' WHERE p.name LIKE ? OR c.name LIKE ?';$params=["%$search%","%$search%"];} $sql.=' ORDER BY p.created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();?>
<section class="admin-actions"><form><input type="hidden" name="page" value="products"><input name="q" value="<?=h($search)?>" placeholder="Search products..."><button>Search</button></form><a class="admin-button" href="<?=admin_url('product')?>">+ Add product</a></section><section class="panel admin-table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td class="product-cell"><img src="<?=h($p['image'])?>" alt=""><span><b><?=h($p['name'])?></b><small><?=$p['is_featured']?'Featured ':''?><?=$p['is_new']?'New arrival':''?></small></span></td><td><?=h($p['category'])?></td><td><?=money(product_price($p))?></td><td><b class="stock-text <?=$p['stock']<1?'zero':($p['stock']<=5?'low':'')?>"><?=$p['stock']?></b></td><td><span class="visibility <?=$p['status']?>"><?=h($p['status'])?></span></td><td class="table-actions"><a href="<?=admin_url('product',['id'=>$p['id']])?>">Edit</a><form method="post" onsubmit="return confirm('Remove this product?')"><?=csrf_input()?><input name="action" value="delete_product" type="hidden"><input name="id" value="<?=$p['id']?>" type="hidden"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$products):?><div class="admin-empty">No matching products yet.</div><?php endif;?></section><?php }

