function admin_orders(): void {$pdo=db();$status=trim($_GET['status']??'');$sql='SELECT o.*,c.full_name,c.phone,c.email FROM orders o JOIN customers c ON c.id=o.customer_id';$params=[];if($status){$sql.=' WHERE o.status=?';$params[]=$status;}$sql.=' ORDER BY o.created_at DESC';$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();$detail=(int)($_GET['detail']??0);?>
<section class="admin-actions status-filters"><form><input type="hidden" name="page" value="orders"><select name="status" onchange="this.form.submit()"><option value="">All order statuses</option><?php foreach(['Pending','Confirmed','Processing','Ready for Delivery','Shipped','Delivered','Cancelled'] as $item):?><option <?=$status===$item?'selected':''?>><?=$item?></option><?php endforeach;?></select></form></section><?php if($detail):$s=$pdo->prepare('SELECT o.*,c.full_name,c.phone,c.email FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?');$s->execute([$detail]);$o=$s->fetch();$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$detail]);if($o):?><section class="order-detail"><a class="back-link" href="<?=admin_url('orders')?>">← All orders</a><div class="panel order-top"><div><p class="eyebrow">order <?=h($o['order_number'])?></p><h2><?=h($o['full_name'])?></h2><p><?=date('F j, Y · g:i a',strtotime($o['created_at']))?></p></div><form method="post" class="status-form"><?=csrf_input()?><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['Pending','Confirmed','Processing','Ready for Delivery','Shipped','Delivered','Cancelled'] as $item):?><option <?=$o['status']===$item?'selected':''?>><?=$item?></option><?php endforeach;?></select><button>Update status</button></form></div><div class="detail-grid"><section class="panel"><h3>Items ordered</h3><?php foreach($items->fetchAll() as $item):?><div class="detail-item"><img src="<?=h($item['product_image'])?>" alt=""><span><b><?=h($item['product_name'])?></b><small>Qty <?=$item['quantity']?> <?=h($item['selected_size']?'· '.$item['selected_size']:'')?> <?=h($item['selected_color']?'· '.$item['selected_color']:'')?></small></span><b><?=money((float)$item['subtotal'])?></b></div><?php endforeach;?><div class="detail-total"><span>Subtotal</span><b><?=money((float)$o['subtotal'])?></b><span>Delivery</span><b><?=money((float)$o['delivery_fee'])?></b><strong>Total</strong><strong><?=money((float)$o['total'])?></strong></div></section><section class="panel"><h3>Delivery details</h3><p><b><?=h($o['full_name'])?></b><br><?=h($o['phone'])?><br><?=h($o['email'])?></p><p><?=h($o['address'])?><br><?=h($o['city'])?>, <?=h($o['state'])?></p><?php if($o['landmark']):?><p><small>Landmark / notes</small><br><?=h($o['landmark'])?></p><?php endif;?></section></div></section><?php endif;else:?><section class="panel admin-table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Phone</th><th>Date</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="<?=admin_url('orders',['detail'=>$o['id']])?>"><?=h($o['order_number'])?></a></td><td><?=h($o['full_name'])?></td><td><?=h($o['phone'])?></td><td><?=date('M j, Y',strtotime($o['created_at']))?></td><td><span class="admin-status <?=order_status_class($o['status'])?>"><?=h($o['status'])?></span></td><td><?=money((float)$o['total'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="admin-empty">No orders have arrived yet.</div><?php endif;?></section><?php endif; }

function admin_inventory(): void {$products=db()->query('SELECT p.*,c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE p.stock<=8 ORDER BY p.stock ASC')->fetchAll();?>
<section class="inventory-callout"><p class="eyebrow">stock watch</p><h2>Keep your favourites<br><i>in reach.</i></h2><p>Products with eight or fewer items appear here. Update stock from the product editor.</p><a class="admin-button" href="<?=admin_url('products')?>">Manage products →</a></section><section class="panel admin-table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Available stock</th><th>Product status</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td class="product-cell"><img src="<?=h($p['image'])?>" alt=""><b><?=h($p['name'])?></b></td><td><?=h($p['category'])?></td><td><b class="stock-text <?=$p['stock']<1?'zero':($p['stock']<=5?'low':'')?>"><?=$p['stock']<1?'Out of stock':$p['stock'].' remaining'?></b></td><td><span class="visibility <?=$p['status']?>"><?=h($p['status'])?></span></td><td><a href="<?=admin_url('product',['id'=>$p['id']])?>">Update stock</a></td></tr><?php endforeach;?></tbody></table><?php if(!$products):?><div class="admin-empty">No low-stock products. Your edit is fully stocked.</div><?php endif;?></section><?php }

function admin_settings(): void {$s=site_settings();?>
<form method="post" class="settings-form panel"><?=csrf_input()?><input type="hidden" name="action" value="save_settings"><p class="eyebrow">store identity</p><h2>Settings</h2><div class="editor-grid"><label>Store name<input name="store_name" value="<?=h($s['store_name'])?>"></label><label>Currency symbol<input name="currency" value="<?=h($s['currency'])?>"></label><label class="wide-field">Store description<textarea name="store_description" rows="3"><?=h($s['store_description'])?></textarea></label></div><p class="eyebrow spacer">contact & delivery</p><div class="editor-grid"><label>Contact phone<input name="contact_phone" value="<?=h($s['contact_phone'])?>"></label><label>Contact email<input type="email" name="contact_email" value="<?=h($s['contact_email'])?>"></label><label>Default delivery fee<input type="number" min="0" step="0.01" name="delivery_fee" value="<?=h($s['delivery_fee'])?>"></label><label>Free delivery threshold<input type="number" min="0" step="0.01" name="free_delivery_threshold" value="<?=h($s['free_delivery_threshold'])?>"></label><label>Store address<input name="store_address" value="<?=h($s['store_address'])?>"></label><label>Instagram / social handle<input name="instagram" value="<?=h($s['instagram'])?>"></label></div><button class="admin-button">Save settings →</button></form><?php }
